 "waypoint.temporaryNote": ["Temporary: removed when you arrive","使い捨て：到達すると消えます","临时：到达后移除","臨時：抵達後移除"],
 "nav.waypoints": ["Waypoints","ウェイポイント","路径点","路徑點"],
 "key.Lamium.openwaypoints": ["Open the Waypoints screen","ウェイポイントの画面を開く","打开路径点界面","開啟路徑點畫面"],
 "waypoint.showAll": ["Show all","すべて表示","全部显示","全部顯示"],
 "waypoint.addHere": ["+ Add here","＋ ここに追加","+ 在此处添加","+ 在此處新增"],
 "waypoint.columnDistance": ["Distance","距離","距离","距離"],
 "waypoint.meters": ["{} m","{} m","{} 米","{} 公尺"],
 "waypoint.distance": ["{} blocks away","{} ブロック先","距离 {} 格","距離 {} 格"],
