 "waypoint.shown": ["Show","表示する","显示","顯示"],
 "waypoint.color": ["Color","色","颜色","顏色"],
 "waypoint.deathName": ["Death point","死亡地点","死亡地点","死亡地點"],
 "waypoint.empty": ["No waypoints yet. Use \"+ Add here\" or the add key.","ウェイポイントはまだありません。「＋ ここに追加」か追加のキーで作れます。","还没有路径点。使用“+ 在此处添加”或添加键。","還沒有路徑點。使用「+ 在此處新增」或新增鍵。"],
 "waypoint.selectHint": ["Select a waypoint in the list. Ctrl or Shift + click selects several.","左の一覧からウェイポイントを選んでください。Ctrl または Shift + クリックで複数選択できます。","请在列表中选择一个路径点。按住 Ctrl 或 Shift 点击可多选。","請在列表中選擇一個路徑點。按住 Ctrl 或 Shift 點擊可多選。"],
 "list.selectedCount": ["{} selected","{} 件を選択中","已选择 {} 项","已選擇 {} 項"],
 "list.showSelected": ["Show","表示","显示","顯示"],
